INSERT IGNORE INTO reporting_queries (slug, name, description, sql_query, is_system)
VALUES
('stat-strip-backup-today', 'Stat Strip - Backup - Today''s Status', 'Used by the backup jobs and backup summary pages. Current status counts for active backup jobs.', 'SELECT COUNT(*) AS jobs, SUM(CASE WHEN COALESCE(e.status, ''unknown'') = ''pass'' THEN 1 ELSE 0 END) AS pass, SUM(CASE WHEN COALESCE(e.status, ''unknown'') = ''warn'' THEN 1 ELSE 0 END) AS warn, SUM(CASE WHEN COALESCE(e.status, ''unknown'') = ''fail'' THEN 1 ELSE 0 END) AS fail, SUM(CASE WHEN e.status IS NULL OR e.status = ''unknown'' THEN 1 ELSE 0 END) AS unknown FROM backup_jobs j LEFT JOIN backup_job_events e ON e.backup_job_id = j.id AND e.event_date = CURRENT_DATE WHERE j.is_active = 1 AND j.company_id = {{current.company}}', 1),
('stat-strip-service-status-company', 'Stat Strip - Service Status - Company Dashboard', 'Tracked service totals by status on the authenticated and public company service-status dashboards.', 'SELECT COUNT(*) AS tracked_services, SUM(CASE WHEN s.status = ''operational'' THEN 1 ELSE 0 END) AS operational, SUM(CASE WHEN s.status = ''maintenance'' THEN 1 ELSE 0 END) AS maintenance, SUM(CASE WHEN s.status = ''degraded'' THEN 1 ELSE 0 END) AS degraded, SUM(CASE WHEN s.status = ''partial_outage'' THEN 1 ELSE 0 END) AS partial_outage, SUM(CASE WHEN s.status = ''outage'' THEN 1 ELSE 0 END) AS outage FROM service_status_services s INNER JOIN service_status_service_companies sc ON sc.service_id = s.id WHERE s.is_active = 1 AND sc.company_id = {{current.company}}', 1),
('stat-strip-service-status-catalogue', 'Stat Strip - Admin - Service Status Catalogue', 'All active services by displayed service status on the administration catalogue.', 'SELECT COUNT(*) AS total, SUM(CASE WHEN status = ''operational'' THEN 1 ELSE 0 END) AS operational, SUM(CASE WHEN status = ''maintenance'' THEN 1 ELSE 0 END) AS maintenance, SUM(CASE WHEN status = ''degraded'' THEN 1 ELSE 0 END) AS degraded, SUM(CASE WHEN status = ''partial_outage'' THEN 1 ELSE 0 END) AS partial_outage, SUM(CASE WHEN status = ''outage'' THEN 1 ELSE 0 END) AS outage FROM service_status_services WHERE is_active = 1', 1),
('stat-strip-customer-tickets', 'Stat Strip - Tickets - Customer Status', 'All customer tickets grouped into the statuses displayed above the ticket list.', 'SELECT COUNT(*) AS all_tickets, SUM(CASE WHEN status = ''open'' THEN 1 ELSE 0 END) AS open, SUM(CASE WHEN status = ''pending'' THEN 1 ELSE 0 END) AS pending, SUM(CASE WHEN status = ''closed'' THEN 1 ELSE 0 END) AS closed, SUM(CASE WHEN status = ''on_hold'' THEN 1 ELSE 0 END) AS on_hold FROM tickets WHERE company_id = {{current.company}}', 1),
('stat-strip-admin-tickets', 'Stat Strip - Admin - Ticketing Workspace', 'Global non-merged ticket totals by technician status in the ticketing workspace.', 'SELECT status AS ticket_status, COUNT(*) AS tickets FROM tickets WHERE merged_into_ticket_id IS NULL GROUP BY status ORDER BY ticket_status', 1),
('stat-strip-defender-overview', 'Stat Strip - Windows Defender - Overview', 'The managed endpoint, active detection, exclusion, and stale-agent counters shown on Windows Defender.', 'SELECT (SELECT COUNT(*) FROM tray_devices td WHERE td.company_id = {{current.company}} AND td.status = ''active'' AND td.defender_managed = 1) AS managed_endpoints, (SELECT COUNT(*) FROM defender_detections dd WHERE dd.company_id = {{current.company}} AND dd.status = ''active'') AS active_detections, (SELECT COUNT(*) FROM defender_exclusions de WHERE de.company_id = {{current.company}}) AS configured_exclusions, (SELECT COUNT(*) FROM tray_devices td WHERE td.company_id = {{current.company}} AND td.status = ''active'' AND (td.last_seen_utc IS NULL OR td.last_seen_utc < UTC_TIMESTAMP() - INTERVAL 15 MINUTE)) AS stale_agents', 1),
('stat-strip-dmarc-overview', 'Stat Strip - DMARC - Overview', 'DMARC message, alignment, disposition, and forensic-failure totals for the last 30 days.', 'SELECT COALESCE(SUM(message_count), 0) AS total_messages, COALESCE(SUM(CASE WHEN r.dkim_result = ''pass'' OR r.spf_result = ''pass'' THEN message_count ELSE 0 END), 0) AS dmarc_pass, COALESCE(SUM(CASE WHEN r.disposition = ''reject'' THEN message_count ELSE 0 END), 0) AS disposition_reject, COALESCE(SUM(CASE WHEN r.disposition = ''quarantine'' THEN message_count ELSE 0 END), 0) AS disposition_quarantine, COALESCE(SUM(CASE WHEN r.disposition = ''none'' THEN message_count ELSE 0 END), 0) AS disposition_none, COALESCE(SUM(CASE WHEN r.spf_result = ''pass'' THEN message_count ELSE 0 END), 0) AS aligned_spf_pass, COALESCE(SUM(CASE WHEN r.dkim_result = ''pass'' THEN message_count ELSE 0 END), 0) AS aligned_dkim_pass, (SELECT COUNT(*) FROM dmarc_forensic_reports f WHERE f.company_id = {{current.company}} AND COALESCE(f.arrival_at, f.created_at) >= UTC_TIMESTAMP() - INTERVAL 30 DAY) AS forensic_failures FROM dmarc_records r INNER JOIN dmarc_reports p ON p.id = r.report_id WHERE r.company_id = {{current.company}} AND p.date_end >= UTC_TIMESTAMP() - INTERVAL 30 DAY', 1),
('stat-strip-m365-best-practices-live', 'Stat Strip - Microsoft 365 - Best Practices', 'Latest Microsoft 365 secure score and check-result counters shown on the interactive best-practices page.', 'SELECT (SELECT secure_score_percentage FROM m365_best_practice_daily_history WHERE company_id = {{current.company}} ORDER BY snapshot_date DESC LIMIT 1) AS secure_score_percentage, COUNT(*) AS checks, SUM(CASE WHEN status = ''pass'' THEN 1 ELSE 0 END) AS passed, SUM(CASE WHEN status = ''fail'' THEN 1 ELSE 0 END) AS failed, SUM(CASE WHEN status = ''unknown'' THEN 1 ELSE 0 END) AS unknown, SUM(CASE WHEN status = ''not_applicable'' THEN 1 ELSE 0 END) AS not_applicable FROM m365_best_practice_results WHERE company_id = {{current.company}} AND run_at = (SELECT MAX(run_at) FROM m365_best_practice_results WHERE company_id = {{current.company}})', 1),
('stat-strip-rag-index', 'Stat Strip - Admin - RAG Index', 'RAG indexing document, chunk, queued-job, and failed-job counters.', 'SELECT (SELECT COUNT(*) FROM rag_documents WHERE is_active = 1) AS active_documents, (SELECT COUNT(*) FROM rag_chunks WHERE is_active = 1) AS active_chunks, (SELECT COUNT(*) FROM rag_index_jobs WHERE status IN (''queued'', ''running'')) AS queued_or_running_jobs, (SELECT COUNT(*) FROM rag_index_jobs WHERE status = ''failed'') AS failed_jobs', 1),
('stat-strip-notifications', 'Stat Strip - Notifications - Overview', 'Company notification totals and unread counts; mirrors the company-scoped portion of the notification strip.', 'SELECT COUNT(DISTINCT n.id) AS total, COUNT(DISTINCT CASE WHEN n.read_at IS NULL THEN n.id END) AS unread_overall FROM notifications n INNER JOIN user_companies uc ON uc.user_id = n.user_id WHERE uc.company_id = {{current.company}}', 1),
('stat-strip-report-assets', 'Stat Strip - Company Overview - Assets', 'Server and workstation assets synced during the last 30 days.', 'SELECT SUM(CASE WHEN LOWER(COALESCE(type, '''')) LIKE ''%server%'' THEN 1 ELSE 0 END) AS servers, SUM(CASE WHEN LOWER(COALESCE(type, '''')) LIKE ''%workstation%'' THEN 1 ELSE 0 END) AS workstations FROM assets WHERE company_id = {{current.company}} AND last_sync >= UTC_TIMESTAMP() - INTERVAL 30 DAY', 1),
('stat-strip-report-backups', 'Stat Strip - Company Overview - Backup History', 'Backup event outcomes and pass rate for the past 30 days.', 'SELECT COUNT(e.id) AS reported_events, SUM(CASE WHEN e.status = ''pass'' THEN 1 ELSE 0 END) AS pass, SUM(CASE WHEN e.status = ''warn'' THEN 1 ELSE 0 END) AS warn, SUM(CASE WHEN e.status = ''fail'' THEN 1 ELSE 0 END) AS fail, SUM(CASE WHEN e.status = ''unknown'' THEN 1 ELSE 0 END) AS unknown, ROUND(100 * SUM(CASE WHEN e.status = ''pass'' THEN 1 ELSE 0 END) / NULLIF(COUNT(e.id), 0), 1) AS pass_rate FROM backup_jobs j LEFT JOIN backup_job_events e ON e.backup_job_id = j.id AND e.event_date >= CURRENT_DATE - INTERVAL 29 DAY WHERE j.company_id = {{current.company}}', 1),
('stat-strip-report-compliance', 'Stat Strip - Company Overview - Compliance Checks', 'Compliance check totals, workflow counts, and review-date alerts.', 'SELECT COUNT(*) AS total_checks, ROUND(100 * SUM(CASE WHEN a.status = ''compliant'' THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0), 1) AS compliance_rate, SUM(CASE WHEN a.status = ''in_progress'' THEN 1 ELSE 0 END) AS in_progress, SUM(CASE WHEN a.status = ''not_started'' THEN 1 ELSE 0 END) AS not_started, SUM(CASE WHEN a.next_review_at < UTC_TIMESTAMP() THEN 1 ELSE 0 END) AS overdue, SUM(CASE WHEN a.next_review_at BETWEEN UTC_TIMESTAMP() AND UTC_TIMESTAMP() + INTERVAL 30 DAY THEN 1 ELSE 0 END) AS due_soon FROM company_compliance_check_assignments a WHERE a.company_id = {{current.company}} AND a.archived = 0', 1),
('stat-strip-report-essential-8', 'Stat Strip - Company Overview - Essential 8', 'Essential 8 compliant, in-progress, and not-started requirement counts by maturity level.', 'SELECT er.maturity_level, SUM(CASE WHEN COALESCE(c.status, ''not_started'') = ''compliant'' THEN 1 ELSE 0 END) AS compliant, SUM(CASE WHEN c.status = ''in_progress'' THEN 1 ELSE 0 END) AS in_progress, SUM(CASE WHEN c.status IS NULL OR c.status = ''not_started'' THEN 1 ELSE 0 END) AS not_started FROM essential8_requirements er LEFT JOIN company_essential8_requirement_compliance c ON c.requirement_id = er.id AND c.company_id = {{current.company}} GROUP BY er.maturity_level ORDER BY er.maturity_level', 1),
('stat-strip-report-huntress-edr', 'Stat Strip - Company Overview - Huntress EDR', 'Latest Huntress EDR incident and investigated-signal counters used by summary and detail strips.', 'SELECT active_incidents, resolved_incidents, signals_investigated FROM huntress_edr_stats WHERE company_id = {{current.company}} ORDER BY snapshot_at DESC LIMIT 1', 1),
('stat-strip-report-huntress-itdr', 'Stat Strip - Company Overview - Huntress ITDR', 'Latest Huntress ITDR investigated-signal counter used by summary and detail strips.', 'SELECT signals_investigated FROM huntress_itdr_stats WHERE company_id = {{current.company}} ORDER BY snapshot_at DESC LIMIT 1', 1),
('stat-strip-report-huntress-sat', 'Stat Strip - Company Overview - Huntress Security Awareness Training', 'Latest Huntress learner, progress, score, click, compromise, and report metrics used by summary and detail strips.', 'SELECT enrolled_learners, avg_completion_rate AS avg_progress, avg_score, phishing_clicks, phishing_compromises, phishing_reports FROM huntress_sat_stats WHERE company_id = {{current.company}} ORDER BY snapshot_at DESC LIMIT 1', 1),
('stat-strip-report-huntress-siem', 'Stat Strip - Company Overview - Huntress Managed SIEM', 'Latest trailing-30-day Huntress SIEM log-volume metric used by summary and detail strips.', 'SELECT data_collected_bytes_30d AS logs_collected_last_30_days FROM huntress_siem_stats WHERE company_id = {{current.company}} ORDER BY snapshot_at DESC LIMIT 1', 1),
('stat-strip-report-huntress-soc', 'Stat Strip - Company Overview - Huntress SOC', 'Latest Huntress SOC analysed-event metric used by summary and detail strips.', 'SELECT total_events_analysed FROM huntress_soc_stats WHERE company_id = {{current.company}} ORDER BY snapshot_at DESC LIMIT 1', 1),
('stat-strip-report-orders-month', 'Stat Strip - Company Overview - Orders This Month', 'Order count for the current calendar month.', 'SELECT COUNT(*) AS orders_this_month FROM shop_orders WHERE company_id = {{current.company}} AND order_date >= DATE_FORMAT(CURRENT_DATE, ''%Y-%m-01'') AND order_date < CURRENT_DATE + INTERVAL 1 DAY', 1),
('stat-strip-report-active-users', 'Stat Strip - Company Overview - Active Users', 'Active non-package staff account count.', 'SELECT COUNT(*) AS active_users FROM staff WHERE company_id = {{current.company}} AND enabled = 1 AND LOWER(SUBSTR(email, 1, 8)) <> ''package_''', 1),
('stat-strip-report-tickets-month', 'Stat Strip - Company Overview - Tickets Past Month', 'Ticket totals by displayed status for the past 30 days.', 'SELECT COUNT(*) AS total, SUM(CASE WHEN status = ''open'' THEN 1 ELSE 0 END) AS open, SUM(CASE WHEN status = ''pending'' THEN 1 ELSE 0 END) AS pending, SUM(CASE WHEN status = ''in_progress'' THEN 1 ELSE 0 END) AS in_progress, SUM(CASE WHEN status = ''resolved'' THEN 1 ELSE 0 END) AS resolved, SUM(CASE WHEN status = ''closed'' THEN 1 ELSE 0 END) AS closed, SUM(CASE WHEN status NOT IN (''open'', ''pending'', ''in_progress'', ''resolved'', ''closed'') THEN 1 ELSE 0 END) AS other FROM tickets WHERE company_id = {{current.company}} AND created_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY', 1),
('stat-strip-report-voice-monitor', 'Stat Strip - Company Overview - Voice Monitor', 'Voice-monitor attempts, availability, connection, failure, answer-time, and duration metrics for the past 30 days.', 'SELECT COUNT(*) AS attempts, ROUND(100 * SUM(CASE WHEN outcome_status = ''passed'' THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0), 1) AS availability, SUM(CASE WHEN outcome_status = ''passed'' THEN 1 ELSE 0 END) AS successful_connections, SUM(CASE WHEN outcome_status IN (''failed'', ''timed_out'', ''exhausted'') THEN 1 ELSE 0 END) AS failures, ROUND(AVG(CASE WHEN answered_at IS NOT NULL THEN TIMESTAMPDIFF(MICROSECOND, started_at, answered_at) / 1000000 END), 1) AS average_answer_time_seconds, ROUND(AVG(duration_seconds), 1) AS average_duration_seconds FROM voice_monitor_attempts WHERE company_id = {{current.company}} AND queued_at >= UTC_TIMESTAMP() - INTERVAL 30 DAY', 1),
('stat-strip-subscription-renewals', 'Stat Strip - Subscriptions - Renewal Forecast', 'Subscription renewals due in 30 and 60 days, projected 90-day revenue, and accounts needing attention.', 'SELECT SUM(CASE WHEN end_date BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL 30 DAY THEN 1 ELSE 0 END) AS renewing_in_30_days, SUM(CASE WHEN end_date BETWEEN CURRENT_DATE + INTERVAL 31 DAY AND CURRENT_DATE + INTERVAL 60 DAY THEN 1 ELSE 0 END) AS renewing_in_60_days, COALESCE(SUM(CASE WHEN end_date BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL 90 DAY THEN quantity * unit_price ELSE 0 END), 0) AS projected_90_day_renewal_revenue, SUM(CASE WHEN status IN (''expired'', ''canceled'') OR (auto_renew = 0 AND end_date <= CURRENT_DATE + INTERVAL 90 DAY) THEN 1 ELSE 0 END) AS accounts_needing_attention FROM subscriptions WHERE customer_id = {{current.company}}', 1),
('stat-strip-report-m365-best-practices', 'Stat Strip - Company Overview - Microsoft 365 Best Practices', 'Microsoft 365 check outcomes and pass rate displayed in the Company Overview report.', 'SELECT COUNT(*) AS checks_run, SUM(CASE WHEN status = ''pass'' THEN 1 ELSE 0 END) AS pass, SUM(CASE WHEN status = ''warn'' THEN 1 ELSE 0 END) AS warn, SUM(CASE WHEN status = ''fail'' THEN 1 ELSE 0 END) AS fail, SUM(CASE WHEN status = ''error'' THEN 1 ELSE 0 END) AS error, SUM(CASE WHEN status = ''not_applicable'' THEN 1 ELSE 0 END) AS not_applicable, SUM(CASE WHEN status = ''unknown'' THEN 1 ELSE 0 END) AS unknown, ROUND(100 * SUM(CASE WHEN status = ''pass'' THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN status IN (''pass'', ''fail'', ''warn'', ''error'') THEN 1 ELSE 0 END), 0), 1) AS pass_rate FROM m365_best_practice_results WHERE company_id = {{current.company}}', 1),
('stat-strip-report-asset-custom-fields', 'Stat Strip - Company Overview - Asset Custom Field Distribution', 'Checkbox custom-field value counts used by both summary and detail strips.', 'SELECT d.name AS field_name, COALESCE(v.value_text, CASE WHEN v.value_boolean = 1 THEN ''Yes'' ELSE ''No'' END) AS field_value, COUNT(*) AS assets FROM asset_custom_field_values v INNER JOIN assets a ON a.id = v.asset_id INNER JOIN asset_custom_field_definitions d ON d.id = v.field_definition_id WHERE a.company_id = {{current.company}} AND d.field_type = ''checkbox'' GROUP BY d.id, d.name, field_value ORDER BY d.display_order, field_value', 1),
('stat-strip-rag-matching', 'Stat Strip - Admin - RAG Relationship Matching', 'RAG relationship matching outcomes, queue health, stored decisions, average lookup time, and matching state.', 'SELECT (SELECT COUNT(DISTINCT source_document_id) FROM rag_relationships WHERE match_status = ''MATCHED'') AS matched_documents, (SELECT COUNT(*) FROM rag_relationship_queue WHERE status IN (''PENDING'', ''PROCESSING'')) AS pending_matches, (SELECT COUNT(*) FROM rag_relationship_queue WHERE status = ''FAILED'') AS failed_lookups, (SELECT COUNT(*) FROM rag_relationships) AS stored_decisions, (SELECT ROUND(AVG(evaluation_duration_ms), 0) FROM rag_relationships) AS average_lookup_time_ms, (SELECT CASE WHEN value = ''1'' THEN ''Paused'' ELSE ''Running'' END FROM rag_matching_state WHERE `key` = ''paused'') AS matching_state', 1),
('stat-strip-bcp-readiness', 'Stat Strip - BCP - Readiness Dashboard', 'Business continuity RTO coverage, backup readiness, exercise cadence, approvals, collaborators, dependencies, and after-action reviews.', 'SELECT ROUND(100 * COUNT(i.id) / NULLIF(COUNT(a.id), 0), 0) AS rto_coverage_percentage, CASE WHEN EXISTS (SELECT 1 FROM bcp_backup_item bi INNER JOIN bcp_plan bp ON bp.id = bi.plan_id WHERE bp.company_id = {{current.company}}) THEN ''Ready'' ELSE ''Gap'' END AS rpo_readiness, (SELECT COUNT(*) FROM bcp_training_item ti INNER JOIN bcp_plan bp ON bp.id = ti.plan_id WHERE bp.company_id = {{current.company}} AND ti.status = ''Completed'' AND ti.training_date >= UTC_TIMESTAMP() - INTERVAL 365 DAY) AS exercise_cadence, (SELECT COUNT(*) FROM bcp_review_item ri INNER JOIN bcp_plan bp ON bp.id = ri.plan_id WHERE bp.company_id = {{current.company}} AND ri.approval_status = ''Approved'') AS approval_snapshots, (SELECT COUNT(*) FROM bcp_role_assignment ra INNER JOIN bcp_role br ON br.id = ra.role_id INNER JOIN bcp_plan bp ON bp.id = br.plan_id WHERE bp.company_id = {{current.company}}) AS collaborators, (SELECT COUNT(*) FROM bcp_dependency_map dm INNER JOIN bcp_plan bp ON bp.id = dm.plan_id WHERE bp.company_id = {{current.company}}) AS dependencies, (SELECT COUNT(*) FROM bcp_incident inc INNER JOIN bcp_plan bp ON bp.id = inc.plan_id WHERE bp.company_id = {{current.company}} AND inc.after_action_reviewed_at IS NOT NULL) AS after_action_reviews FROM bcp_critical_activity a INNER JOIN bcp_plan p ON p.id = a.plan_id LEFT JOIN bcp_impact i ON i.critical_activity_id = a.id AND i.rto_hours IS NOT NULL WHERE p.company_id = {{current.company}}', 1);
